package com.collabspace.security;
import com.collabspace.entity.User; import com.collabspace.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class CustomUserDetailsService implements UserDetailsService { private final UserRepository users; public UserDetails loadUserByUsername(String email)throws UsernameNotFoundException{ User u=users.findByEmail(email).orElseThrow(()->new UsernameNotFoundException("User not found")); return org.springframework.security.core.userdetails.User.withUsername(u.getEmail()).password(u.getPassword()).roles(u.getRole().name()).build(); } }